// Extract user profile and learning goals
const payload = $input.first().json;

return {
  userId: payload.userId,
  userName: payload.userName || 'User',
  userLevel: payload.userLevel || 'beginner',  // beginner, intermediate, advanced
  targetSkills: payload.targetSkills || ['web-security', 'bug-bounty'],
  currentSkills: payload.currentSkills || [],
  learningGoals: payload.learningGoals || 'Become proficient in bug bounty hunting',
  timeCommitment: payload.timeCommitment || '10 hours/week',
  preferredFormat: payload.preferredFormat || 'hands-on',  // hands-on, theoretical, mixed
  requestId: `lp_${Date.now()}`,
  requestedAt: new Date().toISOString()
};

// Aggregate user context for AI analysis
const userProfile = $input.first().json;
const userContent = $input.all().slice(1).map(item => item.json);

// Extract topics and interests from user's blog posts
const topics = new Set();
const categories = new Set();

userContent.forEach(item => {
  if (item.category) categories.add(item.category);
  if (item.tags) {
    const tags = Array.isArray(item.tags) ? item.tags : JSON.parse(item.tags || '[]');
    tags.forEach(tag => topics.add(tag));
  }
});

return {
  ...userProfile,
  userInterests: Array.from(topics),
  contentCategories: Array.from(categories),
  contentCount: userContent.length,
  contextPreparedAt: new Date().toISOString()
};

// Prepare prompt for Fabric AI
const data = $json;

// Build comprehensive prompt for learning path generation
const prompt = `Generate a personalized cybersecurity learning path for the following profile:

**User Profile:**
- Name: ${data.userName}
- Current Level: ${data.userLevel}
- Target Skills: ${data.targetSkills.join(', ')}
- Current Skills: ${data.currentSkills.join(', ') || 'None specified'}
- Learning Goals: ${data.learningGoals}
- Time Commitment: ${data.timeCommitment}
- Preferred Format: ${data.preferredFormat}

**User Interests (based on content):**
${data.userInterests.join(', ')}

**Content Categories:**
${data.contentCategories.join(', ')}

Please create a structured learning path with:
1. Clear milestones (5-7 major milestones)
2. Specific resources and tutorials for each milestone
3. Estimated time for each milestone
4. Prerequisites and skill dependencies
5. Practical projects and exercises
6. Assessment criteria for progression

Focus on bug bounty hunting, web security, and modern cybersecurity practices. Include both free and premium resources.

Format the response as a structured JSON object with the following schema:
{
  "learningPath": {
    "title": "Learning Path Title",
    "description": "Overview",
    "totalDuration": "Estimated total time",
    "milestones": [
      {
        "id": 1,
        "title": "Milestone Title",
        "description": "What you'll learn",
        "duration": "Estimated time",
        "skills": ["skill1", "skill2"],
        "resources": [
          {"title": "Resource", "url": "link", "type": "video/article/course", "free": true}
        ],
        "projects": ["Project description"],
        "assessment": "How to verify completion"
      }
    ]
  }
}`;

return {
  ...data,
  fabricPrompt: prompt,
  promptPreparedAt: new Date().toISOString()
};

// Parse AI response and structure learning path
const aiResponse = $json.message?.content || $json.text || '';
const userData = $input.first().json;

let learningPathData;

try {
  // Try to extract JSON from response
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    learningPathData = JSON.parse(jsonMatch[0]);
  } else {
    // Fallback: create structured data from text
    learningPathData = {
      learningPath: {
        title: `Personalized Learning Path for ${userData.userName}`,
        description: aiResponse.substring(0, 500),
        totalDuration: 'Variable based on pace',
        milestones: [{
          id: 1,
          title: 'Getting Started',
          description: aiResponse.substring(0, 200),
          duration: 'Self-paced',
          skills: userData.targetSkills,
          resources: [],
          projects: [],
          assessment: 'Review and practice'
        }]
      }
    };
  }
} catch (error) {
  learningPathData = {
    learningPath: {
      title: 'Learning Path (Parsing Error)',
      description: 'Error parsing AI response',
      rawResponse: aiResponse,
      error: error.message
    }
  };
}

return {
  userId: userData.userId,
  userName: userData.userName,
  requestId: userData.requestId,
  learningPath: learningPathData.learningPath,
  generatedAt: new Date().toISOString(),
  status: 'completed'
};

parameters.query:
INSERT INTO learning_paths (user_id, request_id, title, description, path_data, status, created_at)
VALUES ($1, $2, $3, $4, $5, $6, NOW())
RETURNING path_id;

