// Create milestone tracking records
const learningPath = $json.learningPath;
const userId = $json.userId;
const pathId = $json.path_id;

if (!learningPath.milestones || !Array.isArray(learningPath.milestones)) {
  return [];
}

return learningPath.milestones.map(milestone => ({
  pathId: pathId,
  userId: userId,
  milestoneId: milestone.id,
  title: milestone.title,
  description: milestone.description,
  duration: milestone.duration,
  skills: JSON.stringify(milestone.skills || []),
  resources: JSON.stringify(milestone.resources || []),
  projects: JSON.stringify(milestone.projects || []),
  assessment: milestone.assessment,
  status: 'not_started',
  progress: 0
}));

